using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> Authorize(int status, string? body)
    {
        using var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        return (outcome, provider);
    }

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        var (_, provider) = await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.ContentType);
        using var json = JsonDocument.Parse(provider.Body!);
        var root = json.RootElement;
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
        Assert.Equal(3, root.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_tolerated()
    {
        var (outcome, _) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_payment_the_provider_refuses_with_402_is_declined()
    {
        var (outcome, _) = await Authorize(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_failures_not_declines(int status)
    {
        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"error":"x"}"""));
        Assert.Equal((System.Net.HttpStatusCode)status, ex.StatusCode);
    }

    [Theory]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("{}")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_treated_as_approved(string body)
    {
        var (outcome, _) = await Authorize(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_malformed_answer_is_a_failure()
    {
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize(200, "<html>oops</html>"));
    }
}
